"use client";

import "./toast.css";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { cx } from "./cx";

export type ToastTone = "default" | "success" | "warning" | "danger" | "info";

type ToastItem = {
  id: string;
  message: ReactNode;
  tone: ToastTone;
};

type ToastContextValue = {
  toast: (
    message: ReactNode,
    options?: { tone?: ToastTone; timeout?: number } | undefined,
  ) => void;
  dismiss: (id: string) => void;
};

const ToastContext = createContext<ToastContextValue | null>(null);

export function useToast() {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error("useToast must be used inside ToastProvider.");
  return ctx;
}

export type ToastProviderProps = {
  children: ReactNode;
};

export function ToastProvider({ children }: ToastProviderProps) {
  const [items, setItems] = useState<ToastItem[]>([]);
  const timers = useRef(new Map<string, number>());

  const dismiss = useCallback((id: string) => {
    const timer = timers.current.get(id);
    if (timer) window.clearTimeout(timer);
    timers.current.delete(id);
    setItems((current) => current.filter((item) => item.id !== id));
  }, []);

  const toast = useCallback(
    (
      message: ReactNode,
      options?: { tone?: ToastTone; timeout?: number } | undefined,
    ) => {
      const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const tone = options?.tone ?? "default";
      const timeout = options?.timeout ?? 4000;
      setItems((current) => [...current, { id, message, tone }]);
      if (timeout > 0) {
        timers.current.set(
          id,
          window.setTimeout(() => dismiss(id), timeout),
        );
      }
    },
    [dismiss],
  );

  useEffect(() => {
    const active = timers.current;
    return () => {
      for (const timer of active.values()) window.clearTimeout(timer);
    };
  }, []);

  return (
    <ToastContext.Provider value={{ toast, dismiss }}>
      {children}
      <div className="ns-toast-region" aria-live="polite" aria-relevant="additions">
        {items.map((item) => (
          <div
            key={item.id}
            className={cx("ns-toast")}
            data-tone={item.tone}
            role="status"
          >
            {item.message}
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

@layer components {
  .ns-toast-region {
    position: fixed;
    inset-block-end: var(--space-8, 1.19rem);
    inset-inline-end: var(--space-8, 1.19rem);
    z-index: var(--z-toast, 30);
    display: flex;
    flex-direction: column;
    gap: var(--space-3, 0.39rem);
    width: min(22rem, calc(100% - var(--space-10, 1.86rem)));
    pointer-events: none;
  }

  .ns-toast {
    padding: var(--space-4, 0.49rem) var(--space-5, 0.61rem);
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
    border-radius: var(--radius, 0.4rem);
    background: var(--bg-overlay, var(--bg, #fff));
    color: var(--text-body, #444);
    box-shadow: none;
    pointer-events: auto;
  }

  .ns-toast[data-tone="success"] {
    border-color: color-mix(in srgb, var(--success, #2f6b3a) 42%, transparent);
    color: var(--success, #2f6b3a);
  }

  .ns-toast[data-tone="warning"] {
    border-color: color-mix(in srgb, var(--warning, #8a5a12) 42%, transparent);
    color: var(--warning, #8a5a12);
  }

  .ns-toast[data-tone="danger"] {
    border-color: color-mix(in srgb, var(--error, #8f3232) 42%, transparent);
    color: var(--error, #8f3232);
  }

  .ns-toast[data-tone="info"] {
    border-color: color-mix(in srgb, var(--info, #2c4a6e) 42%, transparent);
    color: var(--info, #2c4a6e);
  }
}
